// Process structure
type Process = {
  id: number;
  hasToken: boolean;
  nextProcess: Process;
}

// Token Ring implementation
class TokenRing {
  private processes: Process[];

  constructor(numProcesses: number) {
    // Create the process ring
    this.processes = Array.from(
      { length: numProcesses },
      (_, i) => ({
        id: i,
        hasToken: i === 0, // Process 0 starts with the token
        nextProcess: null
      })
    );

    // Connect processes in a ring
    for (let i = 0; i < numProcesses; i++) {
      this.processes[i].nextProcess = 
        this.processes[(i + 1) % numProcesses];
    }
  }

  // Pass the token to the next process
  passToken(process: Process) {
    if (process.hasToken) {
      process.hasToken = false;
      process.nextProcess.hasToken = true;
    }
  }
}

